#include "Vrecam_dss_l1x4_r_static_global_core.h"
#include "DynamicRepairSimulator.hpp"
#include "SimulationConfig.hpp"
#include <algorithm>
#include <array>
#include <cstdint>
#include <exception>
#include <iostream>
#include <optional>
#include <sstream>
#include <stdexcept>

namespace {
using namespace dynamic_spare;
constexpr std::size_t kVectors = 1000, kSas = 4, kDense = 3;
struct Path { unsigned a, b, c, d; };
struct Dense { bool valid = false; unsigned pattern = 0; };
void need(bool ok, const std::string& message) { if (!ok) throw std::runtime_error(message); }
void tick(Vrecam_dss_l1x4_r_static_global_core& dut) { dut.clk_i=0; dut.eval(); dut.clk_i=1; dut.eval(); }
void reset(Vrecam_dss_l1x4_r_static_global_core& dut) { dut.start_i=0; dut.candidate_valid_i=0; dut.candidate_pattern_id_i=0; dut.rst_ni=0; tick(dut); dut.rst_ni=1; tick(dut); }
bool legal(const Path& p) { return p.a < 2U && (p.d == 0U || p.d == 2U) && ((p.b & 2U) == 0U || (p.a & 1U) != 0U) && ((p.c & 2U) == 0U || (p.b & 1U) != 0U) && ((p.d & 2U) == 0U || (p.c & 1U) != 0U); }
std::array<Path,27> paths() { std::array<Path,27> out{}; unsigned n=0; for(unsigned d=0;d<4;++d) for(unsigned c=0;c<4;++c) for(unsigned b=0;b<4;++b) for(unsigned a=0;a<4;++a) { Path p{a,b,c,d}; if(legal(p)) out.at(n++)=p; } need(n==27,"PATH_TABLE"); return out; }
unsigned dense(unsigned action) { return action==3 ? 0 : action; }
unsigned config(unsigned action) { return action==1 ? 4 : (action==2 ? 2 : 0); }
SimulationConfig policy() { SimulationConfig c; c.spareRows=2; c.spareColumns=2; c.sharedRows=1; c.sharedColumns=0; c.layout=GroupLayout::Line1x4; c.topology=SharingTopology::NeighborSharing; c.solutionTakePolicy=SolutionTakePolicy::Line1x4RowStaticGlobal; c.usePaperCamReuseCapacity=true; return c; }
FaultGroup faults(std::uint64_t state) { FaultGroup g; for(std::size_t sa=0;sa<4;++sa) { const auto count=1+((state>>(4*sa))&15); for(std::size_t i=0;i<count;++i) { state=state*6364136223846793005ULL+1442695040888963407ULL; int r=(state>>20)%1024; state=state*6364136223846793005ULL+1442695040888963407ULL; int c=(state>>20)%1024; Fault f{}; f.HBMID=f.ChannelID=f.BankID=f.SubarrayGroupID=0; f.SubarrayID=sa; f.r=r; f.c=c; g[sa].push_back(f); } } return g; }
std::string describe(const FaultGroup& g) { std::ostringstream s; for(std::size_t sa=0;sa<4;++sa) { s<<" SA"<<sa<<":"; for(const auto& f:g[sa]) s<<"("<<f.r<<","<<f.c<<")"; } return s.str(); }
std::array<std::array<Dense,kDense>,kSas> cxxDense(const GroupRepairResult& r) { std::array<std::array<Dense,kDense>,kSas> out{}; for(std::size_t sa=0;sa<4;++sa) { need(r.attemptsBySubarray[sa].size()==2 || r.attemptsBySubarray[sa].size()==3,"DENSE_BANK"); for(const auto& a : r.attemptsBySubarray[sa]) { const unsigned denseIndex = a.availableRows == 1 ? 1U : (a.availableRows == 3 ? 2U : 0U); out[sa][denseIndex].valid=a.repairSuccess&&a.tileSolutionState.has_value()&&!a.validCandidateOptions.empty(); if(out[sa][denseIndex].valid) { auto p=a.validCandidateOptions.front().candidateIndex+1; for(const auto& x:a.validCandidateOptions) p=std::min(p,x.candidateIndex+1); out[sa][denseIndex].pattern=p; } } } return out; }
std::optional<std::pair<unsigned,Path>> choose(const std::array<std::array<Dense,3>,4>& d,const std::array<Path,27>& t) { for(unsigned i=0;i<27;++i) { const auto& p=t[i]; if(d[0][dense(p.a)].valid&&d[1][dense(p.b)].valid&&d[2][dense(p.c)].valid&&d[3][dense(p.d)].valid) return {{i,p}}; } return {}; }
void runVector(Vrecam_dss_l1x4_r_static_global_core& dut, DynamicRepairSimulator& sim,const std::array<Path,27>& table,std::size_t id,std::uint64_t seed,unsigned& rb) { const auto f=faults(seed); const auto cpp=sim.run(f,policy(),id,false); const auto d=cxxDense(cpp); const auto exp=choose(d,table); need(cpp.groupRepairSuccess==exp.has_value(),"HARNESS_ORACLE vector="+std::to_string(id)); reset(dut); dut.start_i=1; tick(dut); dut.start_i=0; for(unsigned e=0;e<12;++e) { dut.eval(); if(!dut.collection_active_o||dut.current_sa_o!=e/3||dut.current_slot_o!=e%3) throw std::runtime_error("SCHEDULE vector="+std::to_string(id)+describe(f)); dut.candidate_valid_i=d[e/3][e%3].valid; dut.candidate_pattern_id_i=d[e/3][e%3].pattern; tick(dut); } dut.eval(); need(dut.allocation_active_o,"DECIDE vector="+std::to_string(id)); tick(dut); dut.eval(); if(!dut.done_o || bool(dut.group_repairable_o)!=exp.has_value()) throw std::runtime_error("FINAL_SOLUTION vector="+std::to_string(id)+describe(f)); if(!exp) return; const auto [pi,p]=*exp; std::array<unsigned,4> a{{p.a,p.b,p.c,p.d}}; unsigned cfg=0,pat=0; for(unsigned sa=0;sa<4;++sa) { auto ac=a[sa], dc=dense(ac); cfg|=config(ac)<<(3*sa); pat|=d[sa][dc].pattern<<(4*sa); if(!cpp.selectedV2Actions[sa]||unsigned(*cpp.selectedV2Actions[sa])!=ac||!cpp.selectedConfigIds[sa]||unsigned(*cpp.selectedConfigIds[sa]) != (ac == 1U ? 1U : (ac == 2U ? 2U : 0U))||!cpp.selectedPatternIds[sa]||*cpp.selectedPatternIds[sa]!=d[sa][dc].pattern) throw std::runtime_error("ACTION_IDENTITY vector="+std::to_string(id)+" P"+std::to_string(pi)+" sa="+std::to_string(sa)+" expected_action="+std::to_string(ac)+" cpp_action="+(cpp.selectedV2Actions[sa]?std::to_string(unsigned(*cpp.selectedV2Actions[sa])):"none")+" expected_dense="+std::to_string(dc)+" cpp_config="+(cpp.selectedConfigIds[sa]?std::to_string(unsigned(*cpp.selectedConfigIds[sa])):"none")+" expected_pattern="+std::to_string(d[sa][dc].pattern)+" cpp_pattern="+(cpp.selectedPatternIds[sa]?std::to_string(*cpp.selectedPatternIds[sa]):"none")+describe(f)); if(ac==3) ++rb; } unsigned release=((p.d&1)<<3)|((p.c&1)<<2)|((p.b&1)<<1)|(p.a&1); unsigned borrow=(((p.d>>1)&1)<<3)|(((p.c>>1)&1)<<2)|(((p.b>>1)&1)<<1)|((p.a>>1)&1); unsigned ledger=release|(((p.b>>1)&1)<<4)|(((p.c>>1)&1)<<7)|(((p.d>>1)&1)*3U<<8); if(dut.sa_commit_valid_o!=15||dut.selected_config_flat_o!=cfg||dut.selected_pattern_flat_o!=pat||dut.release_flat_o!=release||dut.borrow_flat_o!=borrow||dut.ledger_released_borrower_o!=ledger||dut.selected_donor_flat_o!=0x93||dut.failure_position_o!=0) throw std::runtime_error("METADATA vector="+std::to_string(id)+" P"+std::to_string(pi)+describe(f)); }
}
int main(int argc,char** argv) { try { const std::size_t count=argc==2?std::stoul(argv[1]):kVectors; need(count<=kVectors,"vector limit"); auto table=paths(); DynamicRepairSimulator sim; Vrecam_dss_l1x4_r_static_global_core dut; std::uint64_t state=0x475258325f4c5354ULL; unsigned rb=0; for(std::size_t i=0;i<count;++i) { state=state*6364136223846793005ULL+1442695040888963407ULL; runVector(dut,sim,table,i,state,rb); } std::cout<<"LOCKSTEP_VECTORS: "<<count<<"\nLOCKSTEP_MISMATCHES: 0\nLOCAL_RB_ACTION_IDENTITY: PASS selections="<<rb<<"\n"; return 0; } catch(const std::exception& e) { std::cerr<<"LOCKSTEP_MISMATCHES: 1\nFIRST_MISMATCH: "<<e.what()<<"\n"; return 1; } }
